pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title DecentralizedIdentity (Compliance and Verification Registry)
 * @author Expert Solidity Engineer
 * @notice This contract serves as a registry for compliance artifacts, their verification versions, and auditor attestations.
 * It implements role-based access control, pausable functionality, meta-transactions for gasless submissions,
 * and an optional ERC20 staking mechanism for auditors. The contract is named DecentralizedIdentity to meet
 * specific pipeline requirements, where each artifact can represent a unique decentralized entity.
 */
contract DecentralizedIdentity is AccessControl, Pausable, ReentrancyGuard, EIP712 {
    // =============================================================
    //                           Constants & Roles
    // =============================================================

    bytes32 public constant SUBMITTER_ROLE = keccak256("SUBMITTER_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    bytes32 private constant SUBMIT_VERIFICATION_TYPEHASH = keccak256(
        "SubmitVerificationRequest(bytes32 artifactHash,bytes32 resultsHash,string oscalCid,string profileId,uint256 complianceScore,address submitter,uint256 nonce)"
    );

    // =============================================================
    //                             State
    // =============================================================

    // --- Data Model ---
    enum Status { ACTIVE, REVOKED, SUPERSEDED }

    struct Version {
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore; // 0-100
        uint256 verifiedAt;
        address submitter;
        Status status;
        uint256 gasUsed;
    }

    struct Attestation {
        address auditor;
        bool approved;
        bytes32 noteHash;
        uint256 attestedAt;
        uint8 confidenceLevel; // 1-5
    }

    // --- Storage ---
    // Artifact hash => Array of versions
    mapping(bytes32 => Version[]) private _versions;
    // Artifact hash => Version index => Array of attestations
    mapping(bytes32 => mapping(uint256 => Attestation[])) private _attestations;
    // Artifact hash => Version index => Auditor address => Attestation index + 1 (to check existence)
    mapping(bytes32 => mapping(uint256 => mapping(address => uint256))) private _auditorAttestationIndex;

    // --- Reputation ---
    struct SubmitterReputation {
        uint256 validSubmissions;
        uint256 revokedCount;
    }

    struct AuditorReputation {
        uint256 attestationCount;
        uint256 approvalSum; // Count of positive approvals for ratio calculation
    }

    mapping(address => SubmitterReputation) public submitterReputation;
    mapping(address => AuditorReputation) public auditorReputation;

    // --- Staking (Optional) ---
    IERC20 public stakingToken;
    uint256 public requiredStake;
    mapping(address => uint256) public auditorStakes;

    // --- Meta-transactions ---
    mapping(address => uint256) public nonces;

    // =============================================================
    //                             Events
    // =============================================================

    event VerificationSubmitted(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed submitter, bytes32 resultsHash, uint256 complianceScore);
    event VerificationRevoked(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed revoker, bytes32 reasonHash);
    event AttestationAdded(bytes32 indexed artifactHash, uint256 indexed versionIndex, address indexed auditor, bool approved, uint8 confidenceLevel);
    event StakingConfigUpdated(address indexed token, uint256 amount);
    event StakeAdded(address indexed auditor, uint256 amount);
    event StakeRemoved(address indexed auditor, uint256 amount);
    event StakeSlashed(address indexed auditor, address indexed admin, address recipient, uint256 amount);

    // =============================================================
    //                           Constructor
    // =============================================================

    constructor() EIP712("DecentralizedIdentity", "1") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
    }

    // =============================================================
    //                        Core Logic: Submission & Revocation
    // =============================================================

    /**
     * @notice Submits a new verification version for a given artifact.
     * @dev Supersedes the previous active version if one exists.
     * @param artifactHash The unique identifier for the artifact.
     * @param resultsHash A hash of the verification results.
     * @param oscalCid The IPFS CID for the OSCAL document.
     * @param profileId The identifier for the compliance profile used.
     * @param complianceScore The compliance score from 0 to 100.
     */
    function submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string calldata oscalCid,
        string calldata profileId,
        uint256 complianceScore
    ) external whenNotPaused nonReentrant onlyRole(SUBMITTER_ROLE) {
        _submitVerification(artifactHash, resultsHash, oscalCid, profileId, complianceScore, msg.sender);
    }

    /**
     * @notice Revokes the latest active verification for an artifact.
     * @dev Can only be called by an admin or the original submitter of that version.
     * @param artifactHash The identifier of the artifact to revoke.
     * @param reasonHash A hash of the reason for revocation.
     */
    function revokeLatest(bytes32 artifactHash, bytes32 reasonHash) external whenNotPaused nonReentrant {
        uint256 versionCount = _versions[artifactHash].length;
        require(versionCount > 0, "Compliance: No versions exist for artifact");

        Version storage latestVersion = _versions[artifactHash][versionCount - 1];
        require(latestVersion.status == Status.ACTIVE, "Compliance: Latest version is not active");

        require(
            hasRole(DEFAULT_ADMIN_ROLE, msg.sender) || latestVersion.submitter == msg.sender,
            "Compliance: Caller cannot revoke this version"
        );

        latestVersion.status = Status.REVOKED;

        SubmitterReputation storage rep = submitterReputation[latestVersion.submitter];
        rep.revokedCount++;
        // Decrement valid submissions as this is no longer a valid submission
        if (rep.validSubmissions > 0) {
            rep.validSubmissions--;
        }

        emit VerificationRevoked(artifactHash, versionCount - 1, msg.sender, reasonHash);
    }

    // =============================================================
    //                     Core Logic: Attestation
    // =============================================================

    /**
     * @notice Allows an auditor to attest to a specific verification version.
     * @dev An auditor can update their attestation. Requires stake if configured.
     * @param artifactHash The artifact identifier.
     * @param versionIndex The index of the version to attest to.
     * @param approved A boolean indicating approval.
     * @param noteHash A hash of any notes provided by the auditor.
     * @param confidenceLevel The auditor's confidence level (1-5).
     */
    function attest(
        bytes32 artifactHash,
        uint256 versionIndex,
        bool approved,
        bytes32 noteHash,
        uint8 confidenceLevel
    ) external whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        if (requiredStake > 0) {
            require(auditorStakes[msg.sender] >= requiredStake, "Attest: Insufficient stake");
        }
        require(confidenceLevel >= 1 && confidenceLevel <= 5, "Attest: Confidence level out of bounds");

        require(versionIndex < _versions[artifactHash].length, "Attest: Version index out of bounds");
        Version storage version = _versions[artifactHash][versionIndex];
        require(version.status == Status.ACTIVE, "Attest: Can only attest to active versions");

        uint256 attestationIndex = _auditorAttestationIndex[artifactHash][versionIndex][msg.sender];
        AuditorReputation storage rep = auditorReputation[msg.sender];

        if (attestationIndex > 0) { // Update existing attestation
            Attestation storage existingAttestation = _attestations[artifactHash][versionIndex][attestationIndex - 1];

            // Update reputation if approval status changes
            if (existingAttestation.approved && !approved) {
                rep.approvalSum--;
            } else if (!existingAttestation.approved && approved) {
                rep.approvalSum++;
            }

            existingAttestation.approved = approved;
            existingAttestation.noteHash = noteHash;
            existingAttestation.confidenceLevel = confidenceLevel;
            existingAttestation.attestedAt = block.timestamp;
        } else { // Add new attestation
            _attestations[artifactHash][versionIndex].push(Attestation({
                auditor: msg.sender,
                approved: approved,
                noteHash: noteHash,
                attestedAt: block.timestamp,
                confidenceLevel: confidenceLevel
            }));
            _auditorAttestationIndex[artifactHash][versionIndex][msg.sender] = _attestations[artifactHash][versionIndex].length;

            // Update reputation
            rep.attestationCount++;
            if (approved) {
                rep.approvalSum++;
            }
        }

        emit AttestationAdded(artifactHash, versionIndex, msg.sender, approved, confidenceLevel);
    }

    // =============================================================
    //                     Meta-transaction Logic
    // =============================================================

    struct SubmitVerificationRequest {
        bytes32 artifactHash;
        bytes32 resultsHash;
        string oscalCid;
        string profileId;
        uint256 complianceScore;
        address submitter;
        uint256 nonce;
    }

    /**
     * @notice Allows a relayer to submit a verification on behalf of a user.
     * @dev The user must sign a typed data hash (EIP-712) for the request.
     * @param request The struct containing all parameters for the submission.
     * @param signature The user's EIP-712 signature.
     */
    function executeSubmitVerification(
        SubmitVerificationRequest calldata request,
        bytes calldata signature
    ) external whenNotPaused nonReentrant {
        require(request.submitter != address(0), "MetaTx: Invalid submitter");
        require(nonces[request.submitter] == request.nonce, "MetaTx: Invalid nonce");

        bytes32 digest = _hashTypedDataV4(keccak256(abi.encode(
            SUBMIT_VERIFICATION_TYPEHASH,
            request.artifactHash,
            request.resultsHash,
            keccak256(bytes(request.oscalCid)),
            keccak256(bytes(request.profileId)),
            request.complianceScore,
            request.submitter,
            request.nonce
        )));

        address signer = ECDSA.recover(digest, signature);
        require(signer == request.submitter, "MetaTx: Invalid signature");

        nonces[request.submitter]++;

        _submitVerification(
            request.artifactHash,
            request.resultsHash,
            request.oscalCid,
            request.profileId,
            request.complianceScore,
            request.submitter
        );
    }

    // =============================================================
    //                         View Functions
    // =============================================================

    function getVersionCount(bytes32 artifactHash) external view returns (uint256) {
        return _versions[artifactHash].length;
    }

    function getVersion(bytes32 artifactHash, uint256 versionIndex) external view returns (Version memory) {
        return _versions[artifactHash][versionIndex];
    }

    function getAttestations(bytes32 artifactHash, uint256 versionIndex) external view returns (Attestation[] memory) {
        return _attestations[artifactHash][versionIndex];
    }

    function getSubmitterReputation(address submitter) external view returns (SubmitterReputation memory) {
        return submitterReputation[submitter];
    }

    function getAuditorReputation(address auditor) external view returns (uint256 attestationCount, uint256 approvalRatio) {
        AuditorReputation storage rep = auditorReputation[auditor];
        if (rep.attestationCount == 0) {
            return (0, 0);
        }
        // Ratio is in basis points (10000 = 100%)
        uint256 ratio = (rep.approvalSum * 10000) / rep.attestationCount;
        return (rep.attestationCount, ratio);
    }

    // =============================================================
    //                      Staking Functions
    // =============================================================

    /**
     * @notice Sets the staking token and required amount for auditors.
     * @param tokenAddress The address of the ERC20 staking token.
     * @param stakeAmount The amount of tokens required to be staked.
     */
    function setStakingConfig(address tokenAddress, uint256 stakeAmount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        stakingToken = IERC20(tokenAddress);
        requiredStake = stakeAmount;
        emit StakingConfigUpdated(tokenAddress, stakeAmount);
    }

    /**
     * @notice Allows an auditor to stake tokens.
     * @param amount The amount of tokens to stake.
     */
    function stake(uint256 amount) external whenNotPaused nonReentrant onlyRole(AUDITOR_ROLE) {
        require(address(stakingToken) != address(0), "Stake: Staking not configured");
        require(amount > 0, "Stake: Amount must be positive");

        auditorStakes[msg.sender] += amount;
        require(stakingToken.transferFrom(msg.sender, address(this), amount), "Stake: ERC20 transfer failed");

        emit StakeAdded(msg.sender, amount);
    }

    /**
     * @notice Allows an auditor to unstake their tokens.
     * @param amount The amount of tokens to unstake.
     */
    function unstake(uint256 amount) external whenNotPaused nonReentrant {
        require(address(stakingToken) != address(0), "Unstake: Staking not configured");
        require(amount > 0, "Unstake: Amount must be positive");
        require(auditorStakes[msg.sender] >= amount, "Unstake: Insufficient staked amount");

        auditorStakes[msg.sender] -= amount;
        require(stakingToken.transfer(msg.sender, amount), "Unstake: ERC20 transfer failed");

        emit StakeRemoved(msg.sender, amount);
    }

    /**
     * @notice Allows an admin to slash an auditor's stake.
     * @param auditor The address of the auditor to slash.
     * @param amount The amount of stake to slash.
     * @param recipient The address to receive the slashed tokens.
     */
    function slash(address auditor, uint256 amount, address recipient) external whenNotPaused nonReentrant onlyRole(DEFAULT_ADMIN_ROLE) {
        require(address(stakingToken) != address(0), "Slash: Staking not configured");
        require(recipient != address(0), "Slash: Invalid recipient");
        require(amount > 0, "Slash: Amount must be positive");
        require(auditorStakes[auditor] >= amount, "Slash: Insufficient staked amount");

        auditorStakes[auditor] -= amount;
        require(stakingToken.transfer(recipient, amount), "Slash: ERC20 transfer failed");

        emit StakeSlashed(auditor, msg.sender, recipient, amount);
    }

    // =============================================================
    //                       Internal Functions
    // =============================================================

    /**
     * @dev Internal logic for submitting a verification, shared by direct and meta-transactions.
     */
    function _submitVerification(
        bytes32 artifactHash,
        bytes32 resultsHash,
        string memory oscalCid,
        string memory profileId,
        uint256 complianceScore,
        address submitter
    ) internal {
        uint256 gasStart = gasleft();
        require(complianceScore <= 100, "Submit: Score cannot exceed 100");

        uint256 versionCount = _versions[artifactHash].length;

        // Supersede the last version if it was active
        if (versionCount > 0) {
            Version storage lastVersion = _versions[artifactHash][versionCount - 1];
            if (lastVersion.status == Status.ACTIVE) {
                lastVersion.status = Status.SUPERSEDED;
            }
        }

        Version memory newVersion = Version({
            resultsHash: resultsHash,
            oscalCid: oscalCid,
            profileId: profileId,
            complianceScore: complianceScore,
            verifiedAt: block.timestamp,
            submitter: submitter,
            status: Status.ACTIVE,
            gasUsed: 0 // Will be set after all operations
        });

        _versions[artifactHash].push(newVersion);

        submitterReputation[submitter].validSubmissions++;

        uint256 gasUsed = gasStart - gasleft();
        _versions[artifactHash][versionCount].gasUsed = gasUsed;

        emit VerificationSubmitted(artifactHash, versionCount, submitter, resultsHash, complianceScore);
    }

    // =============================================================
    //                      Pausability Control
    // =============================================================

    /**
     * @notice Pauses all critical state-changing functions.
     * @dev Can only be called by an address with the PAUSER_ROLE.
     */
    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses the contract.
     * @dev Can only be called by an address with the PAUSER_ROLE.
     */
    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

